```yaml
name: Test Analysis

on:
  workflow_run:
    workflows: ["Tests"]
    types:
      - completed

jobs:
  test-results:
    runs-on: ubuntu-latest
    if: github.event.workflow_run.conclusion != 'skipped'
    steps:
      - name: Download test artifacts
        uses: actions/github-script@v7
        with:
          script: |
            const artifacts = await github.rest.actions.listWorkflowRunArtifacts({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: ${{ github.event.workflow_run.id }},
            });

            const artifact = artifacts.data.artifacts.find(a => a.name === "test-results");
            if (!artifact) {
              console.log("No test-results artifact found");
              return;
            }

            const download = await github.rest.actions.downloadArtifact({
              owner: context.repo.owner,
              repo: context.repo.repo,
              artifact_id: artifact.id,
              archive_format: 'zip',
            });

            const fs = require('fs');
            fs.writeFileSync('test-results.zip', Buffer.from(download.data), 'binary');

            const unzip = require('unzipper');
            const zip = fs.createReadStream('test-results.zip');
            const extract = zip.pipe(unzip.Extract({ path: './test-results' }));
            await new Promise((resolve, reject) => {
              extract.on('close', resolve);
              extract.on('error', reject);
            })

      - name: Publish test results
        uses: EnricoMi/publish-unit-test-result-action@v2
        if: always()
        with:
          files: test-results/**/*.xml
